15	// A single turn in a chat history. Role is "user" or "assistant".
16	struct ChatTurn {
17	    std::string role;
18	    std::string content;
19	};
20	
21	struct LlmConfig {
22	    std::string host = "localhost";
23	    int port = 11434;
24	    std::string model = "qwen2.5:3b-instruct";
25	    double temperature = 0.8;
26	    int requestTimeoutSeconds = 60;
27	};
28	
29	// One request submitted to the LLM.
30	struct ChatRequest {
31	    std::uint64_t id = 0;
32	    std::string systemPrompt;
33	    std::vector<ChatTurn> history;
34	    std::string userMessage;
35	};
36	
37	// One reply pulled off the queue on the main thread.
38	struct ChatReply {
39	    std::uint64_t id = 0;
40	    bool ok = false;
41	    std::string content;     // model's reply when ok
42	    std::string errorMessage;  // human-readable error when !ok
43	};
44	
45	// Centralized LLM access point. One worker thread serves all NPCs.
46	// Callers submit() requests from the main thread and drainReplies() each frame
47	// to receive completed replies. The id returned from submit() lets callers
48	// match replies back to the request they sent.
49	class LlmClient {
50	   public:
51	    explicit LlmClient(LlmConfig config);
52	    ~LlmClient();
53	
54	    LlmClient(const LlmClient&) = delete;
55	    LlmClient& operator=(const LlmClient&) = delete;
56	
57	    // Enqueue a chat request. Returns a unique id used to correlate replies.
58	    std::uint64_t submit(std::string systemPrompt,
59	                         std::vector<ChatTurn> history,
60	                         std::string userMessage);
61	
62	    // Pop all replies that have arrived since the last call. Non-blocking.
63	    std::vector<ChatReply> drainReplies();
64	
65	    // True while at least one request is in flight or queued. Useful for UI.
66	    bool busy() const { return inFlight_.load(); }
67	
68	    const LlmConfig& config() const { return config_; }
69	
70	   private:
71	    void workerLoop();
72	    ChatReply processOne(const ChatRequest& req);
73	
74	    LlmConfig config_;
75	
76	    std::thread worker_;
77	    std::atomic<bool> stop_{false};
78	    std::atomic<bool> inFlight_{false};
79	
80	    std::mutex requestMutex_;
81	    std::condition_variable requestCv_;
82	    std::queue<ChatRequest> requests_;
83	
84	    std::mutex replyMutex_;
85	    std::vector<ChatReply> replies_;
86	
87	    std::atomic<std::uint64_t> nextId_{1};
88	};
89	
90	}  // namespace llm_npc
