13	LlmClient::LlmClient(LlmConfig config) : config_(std::move(config)) {
14	    worker_ = std::thread(&LlmClient::workerLoop, this);
15	}
16	
17	LlmClient::~LlmClient() {
18	    stop_.store(true);
19	    requestCv_.notify_all();
20	    if (worker_.joinable()) worker_.join();
21	}
22	
23	std::uint64_t LlmClient::submit(std::string systemPrompt,
24	                                std::vector<ChatTurn> history,
25	                                std::string userMessage) {
26	    ChatRequest req;
27	    req.id = nextId_.fetch_add(1);
28	    req.systemPrompt = std::move(systemPrompt);
29	    req.history = std::move(history);
30	    req.userMessage = std::move(userMessage);
31	
32	    {
33	        std::lock_guard<std::mutex> lock(requestMutex_);
34	        requests_.push(std::move(req));
35	    }
36	    requestCv_.notify_one();
37	    return req.id;
38	}
39	
40	std::vector<ChatReply> LlmClient::drainReplies() {
41	    std::vector<ChatReply> out;
42	    std::lock_guard<std::mutex> lock(replyMutex_);
43	    out.swap(replies_);
44	    return out;
45	}
46	
47	void LlmClient::workerLoop() {
48	    while (true) {
49	        ChatRequest req;
50	        {
51	            std::unique_lock<std::mutex> lock(requestMutex_);
52	            requestCv_.wait(lock, [this] { return stop_.load() || !requests_.empty(); });
53	            if (stop_.load() && requests_.empty()) return;
54	            req = std::move(requests_.front());
55	            requests_.pop();
56	        }
57	
58	        inFlight_.store(true);
59	        ChatReply reply = processOne(req);
60	        {
61	            std::lock_guard<std::mutex> lock(replyMutex_);
62	            replies_.push_back(std::move(reply));
63	        }
64	        // Drop the flag only after the reply is queued so UI can poll busy()
65	        // without seeing a brief idle window before the reply lands.
66	        inFlight_.store(false);
67	    }
68	}
