13	// An NPC that delegates dialogue to the shared LlmClient. Holds its own persona
14	// and a bounded conversation history. Many NPCs can share one LlmClient.
15	class Npc {
16	   public:
17	    Npc(Persona persona, LlmClient& client, int maxHistoryTurns = 10);
18	
19	    // Sends the player's line to the LLM. Returns the in-flight request id.
20	    // The reply will appear in client.drainReplies() with that id; pass it back
21	    // into onReplyArrived() to update this NPC's history and surface text.
22	    std::uint64_t ask(const std::string& playerLine);
23	
24	    // Notify this NPC of a reply. Returns the assistant text if the id matches
25	    // a pending request from this NPC; nullopt otherwise. On success, the turn
26	    // is appended to history (capped to maxHistoryTurns_).
27	    std::optional<std::string> onReplyArrived(const ChatReply& reply);
28	
29	    const Persona& persona() const { return persona_; }
30	    const std::vector<ChatTurn>& history() const { return history_; }
31	    bool waiting() const { return pendingId_ != 0; }
32	
33	   private:
34	    Persona persona_;
35	    LlmClient& client_;
36	    int maxHistoryTurns_;
37	    std::vector<ChatTurn> history_;
38	    std::uint64_t pendingId_ = 0;
39	    std::string pendingUserLine_;
40	
41	    void trimHistory();
42	};
43	
44	}  // namespace llm_npc
