9	constexpr float kPadding = 16.f;
10	constexpr float kInputHeight = 48.f;
11	constexpr float kLineHeight = 22.f;
12	constexpr unsigned kFontSize = 16;
13	
14	sf::Color colorFor(TranscriptLine::Kind k) {
15	    switch (k) {
16	        case TranscriptLine::Kind::Player: return sf::Color(180, 220, 255);
17	        case TranscriptLine::Kind::Npc:    return sf::Color(255, 230, 180);
18	        case TranscriptLine::Kind::System: return sf::Color(180, 180, 180);
19	    }
20	    return sf::Color::White;
21	}
22	
23	// Wrap a string to roughly `maxChars` per line. Word-aware: never splits a
24	// word unless the word itself exceeds maxChars. Crude but enough for chat.
25	std::vector<std::string> wrap(const std::string& s, std::size_t maxChars) {
26	    std::vector<std::string> out;
27	    std::string current;
28	    std::string word;
29	    auto flushWord = [&]() {
30	        if (word.empty()) return;
31	        if (current.empty()) {
32	            current = word;
33	        } else if (current.size() + 1 + word.size() <= maxChars) {
34	            current += ' ';
35	            current += word;
36	        } else {
37	            out.push_back(current);
38	            current = word;
39	        }
40	        word.clear();
41	    };
42	    for (char c : s) {
43	        if (c == '\n') {
44	            flushWord();
45	            out.push_back(current);
46	            current.clear();
47	        } else if (c == ' ' || c == '\t') {
48	            flushWord();
49	        } else {
50	            word += c;
51	            if (word.size() > maxChars) {
52	                // Oversized word: hard-break.
53	                if (!current.empty()) {
54	                    out.push_back(current);
55	                    current.clear();
56	                }
57	                out.push_back(word);
58	                word.clear();
59	            }
60	        }
61	    }
62	    flushWord();
63	    if (!current.empty()) out.push_back(current);
64	    return out;
65	}
66	}  // namespace
