102	void DialogUI::setThinking(bool thinking, const std::string& speaker) {
103	    thinking_ = thinking;
104	    thinkingSpeaker_ = speaker;
105	}
106	
107	void DialogUI::setInputEnabled(bool enabled) { inputEnabled_ = enabled; }
