109	void DialogUI::render(sf::RenderTarget& target) const {
110	    const sf::Vector2u sz = target.getSize();
111	    const float w = static_cast<float>(sz.x);
112	    const float h = static_cast<float>(sz.y);
113	
114	    const float transcriptBottom = h - kInputHeight - kPadding;
115	    const std::size_t wrapChars = std::max<std::size_t>(20, static_cast<std::size_t>((w - 2 * kPadding) / 9.0f));
116	
117	    // Collect wrapped, colored lines from newest backward until we run out of
118	    // vertical space. Then render them in chronological order.
119	    struct RenderedLine { std::string text; sf::Color color; };
120	    std::vector<RenderedLine> rendered;
121	    float used = 0.f;
122	    const float available = transcriptBottom - kPadding;
123	
124	    if (thinking_) {
125	        std::string indicator = "... " + (thinkingSpeaker_.empty() ? std::string("(thinking)")
126	                                                                    : thinkingSpeaker_ + " is thinking...");
127	        rendered.push_back({indicator, sf::Color(140, 140, 140)});
128	        used += kLineHeight;
129	    }
130	
131	    for (auto it = transcript_.rbegin(); it != transcript_.rend(); ++it) {
132	        const auto& line = *it;
133	        std::string prefix = line.speaker.empty() ? "" : line.speaker + ": ";
134	        auto wrapped = wrap(prefix + line.text, wrapChars);
135	        // Push in reverse so chronological order is preserved once we reverse the whole vector.
136	        for (auto wi = wrapped.rbegin(); wi != wrapped.rend(); ++wi) {
137	            if (used + kLineHeight > available) break;
138	            rendered.push_back({*wi, colorFor(line.kind)});
139	            used += kLineHeight;
140	        }
141	        if (used + kLineHeight > available) break;
142	    }
143	
144	    std::reverse(rendered.begin(), rendered.end());
145	
146	    float y = transcriptBottom - static_cast<float>(rendered.size()) * kLineHeight;
147	    for (const auto& rl : rendered) {
148	        sf::Text t(rl.text, font_, kFontSize);
149	        t.setFillColor(rl.color);
150	        t.setPosition(kPadding, y);
151	        target.draw(t);
152	        y += kLineHeight;
153	    }
154	
155	    // Input box.
156	    sf::RectangleShape box(sf::Vector2f(w - 2 * kPadding, kInputHeight));
157	    box.setPosition(kPadding, h - kInputHeight - kPadding * 0.5f);
158	    box.setFillColor(sf::Color(30, 30, 36));
159	    box.setOutlineColor(inputEnabled_ ? sf::Color(120, 160, 220) : sf::Color(70, 70, 70));
160	    box.setOutlineThickness(2.f);
161	    target.draw(box);
162	
163	    sf::Text prompt(std::string("> ") + input_ + (inputEnabled_ ? "_" : ""), font_, kFontSize);
164	    prompt.setFillColor(inputEnabled_ ? sf::Color::White : sf::Color(120, 120, 120));
165	    prompt.setPosition(kPadding + 10.f, h - kInputHeight - kPadding * 0.5f + 12.f);
166	    target.draw(prompt);
167	}
