21	// Trim ASCII whitespace from both ends.
22	std::string trim(const std::string& s) {
23	    auto b = s.find_first_not_of(" \t\r\n");
24	    if (b == std::string::npos) return {};
25	    auto e = s.find_last_not_of(" \t\r\n");
26	    return s.substr(b, e - b + 1);
27	}
28	
29	// Tiny key=value config reader; same shape as cpp_racing_game/config/*.cfg.
30	// Lines starting with '#' are comments.
31	std::unordered_map<std::string, std::string> readKv(const fs::path& path) {
32	    std::unordered_map<std::string, std::string> out;
33	    std::ifstream in(path);
34	    if (!in) return out;
35	    std::string line;
36	    while (std::getline(in, line)) {
37	        auto hash = line.find('#');
38	        if (hash != std::string::npos) line = line.substr(0, hash);
39	        line = trim(line);
40	        if (line.empty()) continue;
41	        auto eq = line.find('=');
42	        if (eq == std::string::npos) continue;
43	        out[trim(line.substr(0, eq))] = trim(line.substr(eq + 1));
44	    }
45	    return out;
46	}
47	
48	std::string slurp(const fs::path& path) {
49	    std::ifstream in(path);
50	    if (!in) return {};
51	    std::ostringstream o;
52	    o << in.rdbuf();
53	    return o.str();
54	}
55	
56	llm_npc::LlmConfig loadLlmConfig(const fs::path& configDir) {
57	    llm_npc::LlmConfig cfg;
58	    auto kv = readKv(configDir / "llm.cfg");
59	    if (auto it = kv.find("host"); it != kv.end()) cfg.host = it->second;
60	    if (auto it = kv.find("port"); it != kv.end()) cfg.port = std::stoi(it->second);
61	    if (auto it = kv.find("model"); it != kv.end()) cfg.model = it->second;
62	    if (auto it = kv.find("temperature"); it != kv.end()) cfg.temperature = std::stod(it->second);
63	    if (auto it = kv.find("request_timeout_s"); it != kv.end()) {
64	        cfg.requestTimeoutSeconds = std::stoi(it->second);
65	    }
66	    return cfg;
67	}
