86	// Build the companion's persona. The free-form lines come from
87	// personas/companion.txt so the writing voice can be iterated without a rebuild.
88	llm_npc::Persona buildCompanion(const fs::path& personasDir) {
89	    llm_npc::Persona p;
90	    p.name = "Wren";
91	    p.role = "curious traveling companion";
92	    p.traits = {"warm", "observant", "a little stubborn"};
93	    p.speakingStyle = "1-3 short sentences. Plainspoken. Asks back occasionally.";
94	    p.knowledgeBoundary =
95	        "You know the road, the weather, and rumours from villages you have passed through. "
96	        "You have never heard of computers, code, taxes, sports teams, or modern celebrities; "
97	        "if asked, say so in character.";
98	    std::string extra = slurp(personasDir / "companion.txt");
99	    if (!extra.empty()) p.extraDirectives = extra;
100	    return p;
101	}
