108	GLuint makeCheckerTexture(const sf::Color& a, const sf::Color& b, int cells) {
109	    constexpr int size = 64;
110	    std::vector<std::uint8_t> pixels(size * size * 4, 255);
111	    for (int y = 0; y < size; ++y) {
112	        for (int x = 0; x < size; ++x) {
113	            const int cellX = (x * cells) / size;
114	            const int cellY = (y * cells) / size;
115	            const sf::Color color = ((cellX + cellY) % 2 == 0) ? a : b;
116	            const int i = (y * size + x) * 4;
117	            pixels[i + 0] = color.r;
118	            pixels[i + 1] = color.g;
119	            pixels[i + 2] = color.b;
120	            pixels[i + 3] = 255;
121	        }
122	    }
123	    return createTexture(pixels, size);
124	}
125	
126	GLuint makeStripeTexture(const sf::Color& base, const sf::Color& stripe) {
127	    constexpr int size = 64;
128	    std::vector<std::uint8_t> pixels(size * size * 4, 255);
129	    for (int y = 0; y < size; ++y) {
130	        for (int x = 0; x < size; ++x) {
131	            const bool inStripe = (x / 8) % 2 == 0;
132	            const sf::Color color = inStripe ? stripe : base;
133	            const int i = (y * size + x) * 4;
134	            pixels[i + 0] = color.r;
135	            pixels[i + 1] = color.g;
136	            pixels[i + 2] = color.b;
137	            pixels[i + 3] = 255;
138	        }
139	    }
140	    return createTexture(pixels, size);
141	}
