195	void drawTexturedBox(const Vec3& center,
196	                     float halfX,
197	                     float halfY,
198	                     float halfZ,
199	                     GLuint texture,
200	                     const sf::Color& tint,
201	                     float tileScale = 1.0f) {
202	    const Vec3 lbf{center.x - halfX, center.y - halfY, center.z - halfZ};
203	    const Vec3 rbf{center.x + halfX, center.y - halfY, center.z - halfZ};
204	    const Vec3 rbb{center.x + halfX, center.y - halfY, center.z + halfZ};
205	    const Vec3 lbb{center.x - halfX, center.y - halfY, center.z + halfZ};
206	    const Vec3 ltf{center.x - halfX, center.y + halfY, center.z - halfZ};
207	    const Vec3 rtf{center.x + halfX, center.y + halfY, center.z - halfZ};
208	    const Vec3 rtb{center.x + halfX, center.y + halfY, center.z + halfZ};
209	    const Vec3 ltb{center.x - halfX, center.y + halfY, center.z + halfZ};
210	
211	    bindTexture(texture);
212	    setColor(tint);
213	    glBegin(GL_QUADS);
214	    drawTexturedQuad(ltf, rtf, rtb, ltb, tileScale, tileScale);
215	    drawTexturedQuad(lbf, rbf, rtf, ltf, tileScale, tileScale);
216	    drawTexturedQuad(rbf, rbb, rtb, rtf, tileScale, tileScale);
217	    drawTexturedQuad(rbb, lbb, ltb, rtb, tileScale, tileScale);
218	    drawTexturedQuad(lbb, lbf, ltf, ltb, tileScale, tileScale);
219	    glEnd();
220	}
