571	void updatePlayer(GameState& game, const InputState& input, float dt) {
572	    if (game.won || game.lost) {
573	        return;
574	    }
575	
576	    Vec3 moveDir{};
577	    if (input.moveForward) {
578	        moveDir += flatForward(game.player.yawDeg);
579	    }
580	    if (input.moveBackward) {
581	        moveDir += flatForward(game.player.yawDeg) * -0.75f;
582	    }
583	    if (input.strafeLeft) {
584	        moveDir += flatRight(game.player.yawDeg) * -1.0f;
585	    }
586	    if (input.strafeRight) {
587	        moveDir += flatRight(game.player.yawDeg);
588	    }
589	    if (length(moveDir) > 0.0f) {
590	        game.player.pos += normalize(moveDir) * (kPlayerMoveSpeed * dt);
591	        keepInsideArena(game.player.pos);
592	    }
593	
594	    game.player.shootCooldown = std::max(0.0f, game.player.shootCooldown - dt);
595	    if (input.shoot && game.player.shootCooldown <= 0.0f) {
596	        spawnPlayerShot(game);
597	        game.player.shootCooldown = 0.16f;
598	    }
599	}
