856	void drawImpact(const ImpactEffect& fx, const Vec3& cameraRight, const Vec3& cameraUp) {
857	    const float t = fx.age / std::max(0.001f, fx.lifetime);
858	    const float radius = fx.size * (0.4f + t * 1.8f);
859	    const sf::Color color(fx.color.r, fx.color.g, fx.color.b, static_cast<sf::Uint8>(255.0f * (1.0f - t)));
860	    const Vec3 right = cameraRight * radius;
861	    const Vec3 up = cameraUp * radius;
862	
863	    glDisable(GL_LIGHTING);
864	    glDisable(GL_TEXTURE_2D);
865	    glDepthMask(GL_FALSE);
866	    setColor(color);
867	    glBegin(GL_QUADS);
868	    glVertex3f(fx.pos.x - right.x - up.x, fx.pos.y - right.y - up.y, fx.pos.z - right.z - up.z);
