1035	    glLightfv(GL_LIGHT0, GL_POSITION, lightPos);
1036	
1037	    drawArena(game);
1038	    drawPlayer(game.player);
1039	    for (const auto& enemy : game.enemies) {
1040	        if (enemy.alive) {
1041	            drawEnemy(enemy);
1042	        }
1043	    }
1044	    for (const auto& projectile : game.projectiles) {
1045	        drawProjectile(projectile);
1046	    }
1047	
1048	    drawCrosshair(window);
1049	    window.display();
1050	}
